package com.fctracker.career.telemetry

import com.fctracker.career.AppState
import com.fctracker.career.Player
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNull
import org.junit.Assert.assertSame
import org.junit.Assert.assertTrue
import org.junit.Test

class SquadReportTest {

    // Exactly what FC26_Auto_Capture.lua writes (generated by its own squad_payload function).
    private val payload = """
        {
          "dataType": "squad",
          "title": "Squad contracts",
          "message": "Contracts and loans of 5 players",
          "careerDate": "2026-08-09",
          "players": [
            {"name": "Dani Millán", "pid": 102, "contractEnd": "2027-06-30"},
            {"name": "Fede Bravo", "pid": 103, "contractEnd": "2030-06-30", "loan": {"dir": "in", "club": "Monaco", "end": "2027-07-01", "toBuy": true}},
            {"name": "José Pérez", "pid": 101, "contractEnd": "2031-06-30"},
            {"name": "No Contract", "pid": 105},
            {"name": "Out Loan", "pid": 104, "contractEnd": "2029-06-30", "loan": {"dir": "out", "club": "Parma", "end": "2029-07-01"}}
          ]
        }
    """

    private fun event(json: String = payload, time: Long = 1000): JSONObject =
        JSONObject().put("time", time).put("title", "Squad contracts").put("message", JSONObject(json).toString())

    private fun squad() = listOf(
        Player(id = "1", name = "Jose Perez"),                                   // no accents in the app
        Player(id = "2", name = "Daniel Millán", nickname = "Dani Millán"),      // matched through the nickname
        Player(id = "3", name = "Fede Bravo", loanDirection = "out", loanClub = "Old"),
        Player(id = "4", name = "Out Loan"),
        Player(id = "5", name = "No Contract", contractEnd = "2028-06-30"),
        Player(id = "6", name = "Not In The Report")
    )

    private fun run(state: AppState, vararg events: JSONObject) =
        TelemetryProcessor.apply(state, events.toList(), notify = true, nowSeconds = 2000, today = "2026-08-09")

    @Test
    fun theReportFillsContractsLoansAndTheGamesDate() {
        val result = run(AppState(players = squad()), event())
        val byId = result.state.players.associateBy { it.id }

        assertEquals("2031-06-30", byId.getValue("1").contractEnd)               // "Jose Perez" = "José Pérez"
        assertEquals(101, byId.getValue("1").gamePlayerId)
        assertEquals("2027-06-30", byId.getValue("2").contractEnd)
        assertNull(byId.getValue("2").loanDirection)

        val bravo = byId.getValue("3")
        assertEquals("in", bravo.loanDirection)
        assertEquals("Monaco", bravo.loanClub)
        assertEquals("2027-07-01", bravo.loanEnd)
        assertTrue(bravo.loanOptionToBuy)

        val out = byId.getValue("4")
        assertEquals("out", out.loanDirection)
        assertEquals("Parma", out.loanClub)
        assertFalse(out.loanOptionToBuy)

        assertEquals("2028-06-30", byId.getValue("5").contractEnd)               // the report had none: the old real value stays
        assertNull(byId.getValue("6").contractEnd)                               // not in the report: nothing invented
        assertEquals("2026-08-09", result.state.careerDate)
        assertTrue(result.notices.isEmpty())                                      // stored quietly
        assertTrue(result.state.liveEvents.isEmpty())
    }

    @Test
    fun theSameReportAgainChangesNothing() {
        val first = run(AppState(players = squad()), event()).state
        val again = run(first, event())
        assertSame(first, again.state)
    }

    @Test
    fun aLoanThatEndedIsClearedByTheNextReport() {
        val first = run(AppState(players = squad()), event()).state
        val back = """
            {"dataType":"squad","careerDate":"2027-07-05","players":[
              {"name":"Fede Bravo","pid":103,"contractEnd":"2030-06-30"},
              {"name":"Out Loan","pid":104,"contractEnd":"2029-06-30"}]}
        """
        val after = run(first, event(back)).state.players.associateBy { it.id }
        assertNull(after.getValue("3").loanDirection)
        assertNull(after.getValue("3").loanClub)
        assertNull(after.getValue("3").loanEnd)
        assertFalse(after.getValue("3").loanOptionToBuy)
        assertNull(after.getValue("4").loanDirection)
    }

    @Test
    fun aRenamedPlayerIsStillFoundByTheGamesId() {
        val first = run(AppState(players = squad()), event()).state
        val renamed = first.copy(players = first.players.map {
            if (it.id == "1") it.copy(name = "Nickname Only", customDisplayName = "Pepe") else it
        })
        val moved = payload.replace("2031-06-30", "2033-06-30")
        val after = run(renamed, event(moved)).state.players.associateBy { it.id }
        assertEquals("2033-06-30", after.getValue("1").contractEnd)
    }

    @Test
    fun twoPlayersWithTheSameNameAreNotGuessedAt() {
        val twins = listOf(Player(id = "a", name = "Sam Lee"), Player(id = "b", name = "Sam Lee"))
        val json = """{"dataType":"squad","players":[{"name":"Sam Lee","pid":7,"contractEnd":"2030-06-30"}]}"""
        val result = run(AppState(players = twins), event(json))
        assertTrue(result.state.players.all { it.contractEnd == null })
    }

    @Test
    fun academyPlayersAreUpdatedToo() {
        val json = """{"dataType":"squad","players":[{"name":"Young Gun","pid":9,"contractEnd":"2029-06-30"}]}"""
        val state = AppState(players = emptyList(), academyPlayers = listOf(Player(id = "y", name = "Young Gun", isAcademy = true)))
        val after = run(state, event(json)).state
        assertEquals("2029-06-30", after.academyPlayers.single().contractEnd)
    }

    @Test
    fun badReportsAreHarmless() {
        val bad = listOf(
            """{"dataType":"squad"}""",
            """{"dataType":"squad","players":[]}""",
            """{"dataType":"squad","careerDate":"not a date","players":[{"name":"","pid":1},{"pid":2},{"name":"X","loan":{"dir":"sideways","club":"Y","end":"nope"},"contractEnd":"later"}]}"""
        )
        for (json in bad) {
            val state = AppState(players = squad())
            val result = run(state, event(json))
            assertSame(json, state, result.state)
        }
    }

    @Test
    fun parseKeepsOnlyRealDates() {
        val report = SquadReport.parse(JSONObject("""{"careerDate":"2026-13-40","players":[
            {"name":"A","pid":1,"contractEnd":"2030-06-30","loan":{"dir":"IN","club":"C","end":"junk"}}]}"""))
        assertNull(report.careerDate)
        val row = report.rows.single()
        assertEquals("2030-06-30", row.contractEnd)
        assertEquals("in", row.loanDirection)
        assertNull(row.loanEnd)
    }

    @Test
    fun namesIgnoreAccentsAndPunctuation() {
        assertEquals(SquadReport.normalise("D. Millán"), SquadReport.normalise("d millan"))
        assertEquals("oleary", SquadReport.normalise("O'Leary"))
    }
}
